test('addLine accepts discountPercent for new line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'STICKER', qty: 10, discountPercent: 15 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 15);
});

test('addLine applies tier discount for new line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'STICKER', qty: 10 });
  assert.equal(result.ok, true);
  // C-001 is gold tier, so new line gets 5% discount
  assert.equal(result.value.lines[1].discountPercent, 5);
});

test('addLine updates discountPercent when adding to existing SKU with discount specified', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3, discountPercent: 20 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].discountPercent, 20);
});

test('addLine preserves discountPercent when adding to existing SKU without discount specified', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('addLine reports DISCOUNT_INVALID for invalid discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(addLine(invoiceResult.value, { sku: 'STICKER', qty: 1, discountPercent: 150 }), {
    ok: false,
    error: 'DISCOUNT_INVALID',
  });
});

test('addLine with explicit discount overrides tier discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'STICKER', qty: 10, discountPercent: 0 });
  assert.equal(result.ok, true);
  // Explicit 0 overrides gold tier's 5%
  assert.equal(result.value.lines[1].discountPercent, 0);
});

test('addLine applies silver tier discount to new line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'STICKER', qty: 10 });
  assert.equal(result.ok, true);
  // C-003 is silver tier (2.5% discount)
  assert.equal(result.value.lines[1].discountPercent, 2.5);
});

test('removeLine removes a line by SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'STICKER', qty: 10 },
    ],
  });

  const result = removeLine(invoiceResult.value, 'STICKER');
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
});

test('removeLine reports LINE_NOT_FOUND for unknown SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(removeLine(invoiceResult.value, 'NOPE'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine reports NO_LINES when removing the last line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(removeLine(invoiceResult.value, 'DES-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine reports NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'paid',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'STICKER', name: 'Sticker sheet', qty: 10, unitPrice: 50, vatRate: 21 },
    ],
  };

  assert.deepEqual(removeLine(invoice, 'STICKER'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine does not mutate the input invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'STICKER', qty: 10 },
    ],
  });

  const invoice = invoiceResult.value;
  const originalLineCount = invoice.lines.length;

  removeLine(invoice, 'STICKER');

  assert.equal(invoice.lines.length, originalLineCount);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = issueInvoice(invoiceResult.value, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.number, 'INV-2024-0001');
  assert.equal(result.value.customerId, 'C-001');
});

test('issueInvoice with existing numbers', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-06-20',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });

  const result = issueInvoice(invoiceResult.value, ['INV-2024-0001', 'INV-2024-0002']);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0003');
});

test('issueInvoice assigns new number for new year', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const result = issueInvoice(invoiceResult.value, [
    'INV-2024-0010',
    'INV-2024-0020',
  ]);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2025-0001');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(issueInvoice(invoice, []), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('issueInvoice does not mutate the input invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;
  const originalStatus = invoice.status;

  issueInvoice(invoice, []);

  assert.equal(invoice.status, originalStatus);
  assert.equal(invoice.number, undefined);
});

test('issueInvoice preserves all other invoice fields', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-03-10',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });

  const result = issueInvoice(invoiceResult.value, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.issueDate, '2024-03-10');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].name, 'Sticker sheet');
});
